<node TEXT="CHECK_PROMPT" ID="ID_706442367" CREATED="1789665211200" MODIFIED="1789665266112"><richcontent TYPE="DETAILS" HIDDEN="true">
<html>
  <head>
    
  </head>
  <body>
    <div style="color: #bbbebf; background-color: #121314; font-family: Consolas, Courier New, monospace; font-weight: normal; font-size: 14px; line-height: 19px; white-space: pre">
      <div>
        <span style="color: #a5d6ff;">&quot;&quot;&quot;</span>
      </div>
      <div>
        <span style="color: #a5d6ff;">You are verifying facts against a source text chunk. For each checklist item, respond in this exact format:</span>
      </div>
      <div>
        <span style="color: #a5d6ff;">ITEM: &lt;checklist item&gt;</span>
      </div>
      <div>
        <span style="color: #a5d6ff;">ANSWER: YES or NO or &lt;number&gt;</span>
      </div>
      <div>
        <span style="color: #a5d6ff;">QUOTE: &lt;exact sentence from the chunk that supports your answer, copied verbatim or NOT FOUND&gt;</span>
      </div>
      <br/>
      

      <div>
        <span style="color: #a5d6ff;">Do not paraphrase the quote. Do not answer YES if you cannot produce an exact quote.</span>
      </div>
      <br/>
      

      <div>
        <span style="color: #a5d6ff;">CHUNK: </span><span style="color: #ff7b72;">{CHUNK}</span>
      </div>
      <div>
        <span style="color: #a5d6ff;">CHECKLIST: </span><span style="color: #ff7b72;">{CHECKLIST}</span><span style="color: #a5d6ff;">&#xa0; </span>
      </div>
      <div>
        <span style="color: #a5d6ff;">&quot;&quot;&quot;</span>
      </div>
    </div>
  </body>
</html></richcontent>
</node>
